function stripHtml(html) {
  return String(html || "")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<\/p>/gi, "\n")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'");
}

function stripQuoted(text) {
  const lines = String(text || "").split(/\r?\n/);
  const out = [];
  for (const line of lines) {
    const t = line.trim();
    if (/^On .+wrote:?$/i.test(t) || /^-{2,}\s*Original Message/i.test(t) || /^From:\s.+/i.test(t) && out.length > 0 || /كتب:?$/.test(t) || /^_{5,}$/.test(t)) break;
    if (t.startsWith(">")) continue;
    out.push(line);
  }
  return out.join("\n");
}

const emails = $input.all().filter(i => i.json && i.json.id);
const blocks = emails.map((item, idx) => {
  const e = item.json;
  const from = (e.from && (e.from.text || (e.from.value && e.from.value[0] && e.from.value[0].address))) || e.From || "Unknown";
  const subject = e.subject || e.Subject || "(no subject)";
  let body = e.text && String(e.text).trim() ? e.text : stripHtml(e.html || e.textAsHtml || "");
  if (!body || !String(body).trim()) body = e.snippet || "";
  body = stripQuoted(body).replace(/[ \t]+/g, " ").replace(/\n{3,}/g, "\n\n").trim().slice(0, 800);
  return (idx + 1) + ". From: " + from + "\nSubject: " + subject + "\nBody: " + body;
});

return [{ json: { emailCount: emails.length, emailText: blocks.join("\n\n---\n\n") } }];

const LIMIT = 4000;
function esc(s) {
  return String(s || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}
const summary = esc($input.first().json.text).trim();
const date = $now.setZone("Asia/Hebron").toFormat("yyyy-MM-dd");
const header = "<b>📬 ملخص بريد اليوم</b>\n" + date + "\n\n";
const full = header + summary;

const chunks = [];
if (full.length <= LIMIT) {
  chunks.push(full);
} else {
  let current = header;
  for (const line of summary.split("\n")) {
    let piece = line;
    while (piece.length > LIMIT) {
      if (current.trim()) { chunks.push(current); current = ""; }
      chunks.push(piece.slice(0, LIMIT));
      piece = piece.slice(LIMIT);
    }
    if ((current + piece + "\n").length > LIMIT) {
      chunks.push(current);
      current = "";
    }
    current += piece + "\n";
  }
  if (current.trim()) chunks.push(current);
}

return chunks.map((message, i) => ({ json: { message: message.trim(), part: i + 1, totalParts: chunks.length } }));
